import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>按正确的步骤来，把图片缩小到100KB只要五分钟。流程很简单，但细节决定了结果好不好看。</p>\n<p>这篇指南覆盖完整的工作流。你会选对原图、选好格式、跑完压缩，并在使用之前验证结果。</p>\n<p>它适用于简历、招聘网站、博客图片和邮件配图，电脑和手机都能操作。</p>\n<h2 id=\"what-you-need\">开始之前需要准备什么？</h2>\n<p>你需要原始的图片文件。相机相册里的照片最理想，通过聊天软件转发过的副本已经受损了。</p>\n<p>确认图片要用在哪里。简历网站可能只接受JPG，博客则可能也接受WebP。</p>\n<p>如果有尺寸要求，也记下来。有些表格既要求文件大小，又要求像素尺寸，两项都要满足。</p>\n<p>最后，原图一定要保存好。千万别用压缩版覆盖它，万一要重试还能找回来。</p>\n<h2 id=\"step-1-open-the-tool\">第一步：打开100KB工具</h2>\n<p>在浏览器里打开<a href=\"/zh/tupian-yasuo-dao-100kb/\">图片压缩到100KB工具</a>。不需要账号，也不用安装。</p>\n<p>工具完全在你的设备上运行。照片在本地处理，永远不会上传到服务器。</p>\n<p>手机上操作也一样。点一下上传区域，从相册里选照片就行。</p>\n<p>如果你经常压缩图片，可以把页面加入收藏。100KB这个尺寸，你会一次又一次地回来用。</p>\n<h2 id=\"step-2-upload\">第二步：上传图片</h2>\n<p>把文件拖到页面上，或者点一下浏览选择。支持JPG、PNG、WebP和HEIC，单个文件最大25MB。</p>\n<p>上传你手里画质最高的版本。1200万像素的原图能给压缩器留出大得多的发挥空间，小副本就不行。</p>\n<p>批量处理时，可以一次选多个文件。每张都会被压到100KB，然后一起打包成ZIP下载。</p>\n<p>改设置之前，等上传完成。工具需要拿到完整的文件，才能搜索最佳画质。</p>\n<h2 id=\"step-3-choose-format\">第三步：选择输出格式</h2>\n<p>照片用JPG是最安全的默认选择。它到处都被接受，100KB下结果也很干净。</p>\n<p>如果目的地接受WebP、而你又想要最锐利的结果，就选WebP。同样大小下，WebP的边缘常常会干净一点点。</p>\n<p>PNG只留给颜色扁平、线条锐利或带透明背景的图形。照片存成PNG，很难压到100KB。</p>\n<p>拿不准时，就让格式保持自动。工具可以在需要时帮你把大PNG转过去。</p>\n<h2 id=\"step-4-run-compression\">第四步：运行压缩</h2>\n<p>工具会自动运行二分画质搜索。它会测试不同的画质档位，直到找到能塞进100KB的最高画质。</p>\n<p>你不用自己选画质百分比。搜索会为你的这张图片找到最合适的数字。</p>\n<p>留意“小于100KB”的确认信息。有这个徽章，就说明文件通过了上限，可以直接用了。</p>\n<p>如果工具提示目标没达成，把格式换成JPG或者允许缩放尺寸，再跑一次。</p>\n<h2 id=\"step-5-preview\">第五步：仔细预览结果</h2>\n<p>下载之前，用全尺寸预览压缩后的图片。小缩略图会藏住问题，全尺寸下一眼就能看出来。</p>\n<p>先看脸部。眼睛要保持锐利，皮肤要平滑自然，不能出现斑驳或塑料感。</p>\n<p>再看文字。图片里的任何文字都必须保持可读，截图和证书尤其如此。</p>\n<p>如果有对比视图，一定要用。原图和压缩版并排放在一起，细小的损伤最容易发现。</p>\n<h2 id=\"step-6-download\">第六步：下载并整理</h2>\n<p>下载文件。文件名会标明这是100KB版本，不会和原图弄混。</p>\n<p>在设备上检查文件大小。它应该略低于100KB，通常在98KB到99.9KB之间。</p>\n<p>把压缩版放在原图旁边，而不是代替原图。两者都留着，以后想换设置重试随时可以。</p>\n<p>批量处理时，下载ZIP并解压到单独的文件夹。如果自动生成的名字不够清楚，就重命名一下。</p>\n<h2 id=\"fixing-problems\">常见问题的修复方法</h2>\n<p>图片看起来模糊，可能是原图本身就太小了。从更大的原图重新开始，再压缩一次。</p>\n<p>目标没达成时，换成JPG并允许缩放。这两个改动能解决大多数失败。</p>\n<p>颜色看起来不对时，检查图片是不是带透明背景。透明PNG转成JPG时，背景会被填成白色，通常就是白色。</p>\n<p>文件反而变大了，说明格式和内容不匹配。工具会提醒你这一点，换个格式重试就行。</p>\n<h2 id=\"resume-photo-workflow\">实战：简历照片</h2>\n<p>选一张背景干净、光线好的证件照。干净的原图能让整个工作轻松很多。</p>\n<p>上传到100KB工具，格式保持JPG。大多数招聘网站在接受的格式里都把JPG排在第一位。</p>\n<p>用全尺寸预览脸部。确认眼睛锐利、背景没有色带。</p>\n<p>下载文件并上传到招聘网站。如果网站显示预览，先确认照片显示正常再提交。</p>\n<h2 id=\"blog-thumbnail-workflow\">实战：博客缩略图</h2>\n<p>把一组文章的缩略图收集起来，一次性批量上传。每张都会被压到100KB。</p>\n<p>如果你的博客平台支持WebP，就用WebP。几十张图片累积下来，这点画质提升很可观。</p>\n<p>抽查三四张结果，不要只看第一张。一张坏结果很容易藏在一堆好结果中间。</p>\n<p>下载ZIP、解压，然后上传到博客。原图留着，万一某篇文章以后需要更大的图片还能用。</p>\n<h2 id=\"phone-workflow\">实战：手机上操作</h2>\n<p>在手机浏览器里打开工具，点一下上传区域。从相册里选原图。</p>\n<p>苹果手机的照片可能是HEIC格式。直接上传就行，工具会在压缩过程中完成转换。</p>\n<p>在手机屏幕上预览结果，再双指放大。下载之前检查脸部和文字。</p>\n<p>在“文件”应用里找到下载的文件，确认大小。然后按需要把它附到表格或邮件上。</p>\n<h2 id=\"certificate-scans\">缩小证书和证件扫描件</h2>\n<p>证书扫描是常见的100KB任务。它们混合了印刷文字、印章，有时还有一张小照片，比单纯的人像更难处理。</p>\n<p>300 DPI的扫描是最佳平衡。分辨率更高会造出巨大的文件、被迫压得更狠，分辨率更低则会让文字变糊。</p>\n<p>压缩后预览最小的文字。脚注、注册号和签名是最先受损的地方。</p>\n<p>文字发虚时，试试WebP输出。同样文件大小下，WebP的小字比JPG更干净。</p>\n<p>每张证书都要留一份高分辨率的副本。网站以后可能要求更大的版本，而100KB的文件没法干净地放大。</p>\n<h2 id=\"comparing-results\">正确使用对比视图</h2>\n<p>对比视图会把原图和压缩版并排显示。每次都用它，因为眼睛并排看时，发现损伤的速度最快。</p>\n<p>在两张图片的同一个位置看。挑一个细节多的区域，比如头发或小字，在两个版本里仔细对比。</p>\n<p>来回切换几次。单看一眼发现不了的差别，快速切换时常常会冒出来。</p>\n<p>按图片实际使用的尺寸来判断。放大到300%才看得见的缺陷，在正常显示尺寸下可能根本不重要。</p>\n<p>对比确实发现了损伤，就改一个设置重试。换格式是最快的单项修复。</p>\n<h2 id=\"auto-convert-png\">“自动转换大PNG”选项</h2>\n<p>工具提供一个自动转换大PNG的选项。打开后，PNG照片会在压缩过程中被转成JPG或WebP。</p>\n<p>处理照片时就让它开着。PNG照片几乎总是压缩失败的原因，转换一下立刻就能解决。</p>\n<p>带透明背景的图形要关掉它。透明PNG转成JPG时背景会被填成白色，可能不是你想要的效果。</p>\n<p>这个开关只影响大PNG。小PNG图形不会被动，标志和图标都保持原样。</p>\n<p>拿不准时，先开着开关试一次压缩。结果不对的话，再关掉重跑一次。</p>\n<h2 id=\"recompress-warning\">“重新压缩”警告是什么意思？</h2>\n<p>有时候工具会警告，文件在压缩过程中反而变大了。这发生在输入文件本身已经被重度压缩过的时候。</p>\n<p>文件变大了就是停下来的信号。原图已经比工具能做出来的更小，直接用原图就行。</p>\n<p>这个警告最常出现在从网上下载的文件上。它们已经被提供它们的网站压过一次了。</p>\n<p>看到这个警告后，千万别强行再压缩。每一轮都会叠加损伤，文件只会越来越大、越来越难看。</p>\n<p>诚实的办法是保留原文件。它已经满足你的尺寸需求，任何工具都没法再改进它。</p>\n<h2 id=\"keeping-originals-safe\">保护好你的原图</h2>\n<p>压缩是单向过程。细节一旦扔掉，任何工具都找不回来。</p>\n<p>原图和压缩副本分文件夹存放。泾渭分明，就不会不小心覆盖掉原图。</p>\n<p>原图要备份到安全的地方。云端文件夹或移动硬盘，能在手机丢失时保护你。</p>\n<p>压缩文件要标清楚。名字里带上100kb，未来的你一眼就知道这个文件是什么、为什么这么小。</p>\n<p>要求变了，就从原图重新压缩。花一分钟时间，结果一定比再压缩一个副本要好。</p>\n<h2 id=\"team-workflows\">团队的100KB工作流</h2>\n<p>一起发布内容的团队需要一个共同标准。约定每张图片100KB，就不用每个人各自猜测了。</p>\n<p>把标准写下来：格式、尺寸和命名。团队维基里的一页指南，能省掉上百个小问题。</p>\n<p>把工具链接分享给新同事。一个100KB压缩工具的收藏夹，比长篇大论的压缩理论有用得多。</p>\n<p>发布前抽查一批结果。五十张缩略图里混进一张坏的，很容易漏掉，发出去了又很尴尬。</p>\n<p>原图放在共享云盘里。标准变了，团队可以从母版重新压缩，不用到处找文件。</p>\n<h2 id=\"alt-text-seo\">100KB下的替代文字、文件名与SEO</h2>\n<p>文件大小影响速度，速度影响搜索排名。同样一个页面，图片每张100KB比每张2MB加载更快、排名更好。</p>\n<p>文件名也很重要。blue-cotton-shirt-100kb.jpg这样的描述性名字，能告诉搜索引擎图片里是什么。</p>\n<p>替代文字是最重要的部分。用一句话描述图片，带上搜索者会找的关键细节。</p>\n<p>不要在替代文字里堆关键词。自然的描述对读者和搜索引擎都有帮助，堆关键词对谁都没用。</p>\n<p>压缩、命名和替代文字是配合工作的。页面又快、图片描述又清楚，这就是目标，而100KB正是让它变容易的尺寸。</p>\n<h2 id=\"measuring-improvement\">衡量压缩后的改善</h2>\n<p>压缩前后的数字能让好处变得具体。记下几张图片的原始大小和压缩后大小，对比一下。</p>\n<p>一张普通的手机照片通常从4MB降到100KB，省了97%以上。这个数字值得分享给团队或客户。</p>\n<p>页面速度也要测一测。图片都压到100KB后，一个原来要八秒加载的页面可能两秒就好了。</p>\n<p>用免费的速度工具检查。它们会报告图片的总重量，并标出仍然太重的图片。</p>\n<p>简单记录一下省下来的数据。有人问为什么图片必须压缩时，数字比任何争论都有说服力。</p>\n<h2 id=\"rounding-note\">关于文件大小与四舍五入</h2>\n<p>文件大小按字节测量，但设备显示的是四舍五入后的数字。手机上显示100KB的文件，实际可能是100.4KB，严格的网站会拒绝它。</p>\n<p>工具测量的是精确的字节数，并且会瞄准上限以下一点点。相信它的徽章，而不是设备上四舍五入后的数字。</p>\n<p>想了解100KB为什么这么好用，可以读<a href=\"/zh/blog/tu-pian-ya-suo-dao-100kb-wan-zheng-zhi-nan/\">图片压缩到100KB：完整指南</a>。想看详细的格式对比，可以看<a href=\"/zh/blog/100kb-tu-pian-zhi-liang-jpg-png-webp-dui-bi/\">100KB图片画质：JPG、PNG、WebP对比</a>。如果某个严格的表格需要更小的文件，可以试试<a href=\"/zh/tupian-yasuo-dao-50kb/\">50KB压缩工具</a>。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"能把图片精确压到100KB吗？","answer":"工具瞄准的是略低于100KB，通常在98KB到99.9KB之间，而不是正好100KB。留出这点安全余量，是为了避开不同系统之间字节四舍五入的差异。如果需要精确的自定义数字，可以用目标文件大小压缩工具。"},{"question":"把照片压到100KB，最好的格式是什么？","answer":"JPG是最安全、适用面最广的选择，到处都被接受。目的地接受WebP时，同样大小下WebP的结果会干净一点点。照片不要用PNG，它很难在不大幅裁尺寸的情况下到达100KB。"},{"question":"能把PNG截图压到100KB又不让文字变糊吗？","answer":"大多数情况下可以。截图在100KB下压得很好，文字通常保持可读。文字发虚时，试试WebP输出，或者允许小幅缩小尺寸，而不是大幅降低画质。下载之前先放大预览一下。"},{"question":"一次能把多少张图片压到100KB？","answer":"可以一次加入多张图片，打包成ZIP一起下载，没有每日限额。手机内存有限时，特别大的批量处理可能会变慢，必要时拆成小组分批处理。"},{"question":"压到100KB会删掉图片的元数据吗？","answer":"会，压缩过程中会去掉相机的EXIF标签和GPS位置数据。这通常是好事，尤其是公开分享的照片。除了压缩本身，图片内容没有其他改动。"},{"question":"我的图片已经只有90KB了，还需要跑一遍工具吗？","answer":"不需要。文件已经小于你的上限，再压缩只会白白增加损伤，没有任何好处。直接用这个文件就行。如果文件在重新压缩时反而变大，工具自己也会警告你。"}];
